const body = $json.body;

const collateralsText = (body.collaterals || [])
  .map((c) => `- ${c.type}: ${c.value} Toman`)
  .join('\n') || 'None';

const prompt = `You are a loan risk assessment engine for a bank's pre-assessment system.

Applicant monthly income (Toman): ${body.monthly_income}
Requested amount (Toman): ${body.requested_amount}
Repayment period (months): ${body.repayment_months}
Collateral offered:
${collateralsText}

Analyze the debt-to-income ratio and collateral coverage, then respond with ONLY a JSON object (no other text, no markdown fences) matching exactly this shape:
{"risk_score": <integer 0-100, higher is riskier>, "risk_level": "low" or "medium" or "high", "reasoning": "<2-3 sentence explanation in Persian>", "policy_reference": "<short policy note or null>"}`;

return [
  {
    json: {
      model: 'llama3.2:3b',
      format: 'json',
      stream: false,
      prompt,
    },
  },
];

const webhookData = $('Webhook').first().json.body;
const aiRaw = $input.first().json.response;

let parsed;
try {
  parsed = JSON.parse(aiRaw);
} catch (e) {
  const match = String(aiRaw).match(/\{[\s\S]*\}/);
  parsed = match
    ? JSON.parse(match[0])
    : {
        risk_score: 50,
        risk_level: 'medium',
        reasoning: 'AI response could not be parsed automatically; defaulted to medium risk for manual review.',
        policy_reference: null,
      };
}

return [
  {
    json: {
      application_id: webhookData.application_id,
      risk_score: parsed.risk_score,
      risk_level: parsed.risk_level,
      reasoning: parsed.reasoning,
      policy_reference: parsed.policy_reference ?? null,
    },
  },
];
